package dan200.computercraft.core.internet;

/**
 * A sink for events generated by the {@link NetStack}, which the mod layer forwards to the computer's Lua runtime
 * (via {@code IComputerAccess#queueEvent}).
 * <p>
 * Event arguments are restricted to simple types ({@link String}, {@link Integer}, {@code byte[]} and
 * {@code String[]}), so that the mod layer can convert them to Lua values without needing any knowledge of the stack.
 * <p>
 * The events currently emitted are:
 * <ul>
 *     <li>{@code net_message(address: string, port: number, message: string)} - a message was received by a listening
 *     socket.</li>
 *     <li>{@code net_connect(socket: number, address: string, port: number)} - a connection was established.</li>
 *     <li>{@code net_disconnect(socket: number, address: string, port: number, reason: string)} - a connection was
 *     closed, either locally or by the remote.</li>
 *     <li>{@code net_dhcp(address: string, netmask: string, gateway: string)} - a DHCP lease was acquired. On failure
 *     all three arguments are the empty string.</li>
 * </ul>
 */
public interface NetEventSink {
    /**
     * Queue an event to be delivered to the computer.
     *
     * @param event The name of the event.
     * @param args  The arguments to the event. These must be simple types.
     */
    void queueEvent(String event, Object... args);
}
